function initHeroMotion(){const hero=$('.hero'),art=$('.art');if(!hero||!art||matchMedia('(prefers-reduced-motion: reduce)').matches||!matchMedia('(pointer: fine)').matches)return;hero.onpointermove=e=>{const r=hero.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;hero.style.setProperty('--glow-x',`${Math.round(x*100)}%`);hero.style.setProperty('--glow-y',`${Math.round(y*100)}%`);art.style.translate=`${Math.round((x-.5)*20)}px ${Math.round((y-.5)*16)}px`};hero.onpointerleave=()=>{hero.style.setProperty('--glow-x','76%');hero.style.setProperty('--glow-y','44%');art.style.translate='0 0'}}
function explore(){mode='prematch';if(currentAccount)go('ev');else location.href='/signin?next=%2Fev'}function pricing(){return `<div class="pricing-intro"><div class="eyebrow">INVEST IN YOUR PROCESS</div><h1>Choose your edge.</h1><p>Focused tools. Transparent pricing. A plan for the way you play.</p><span class="tag">MONTHLY MEMBERSHIPS</span></div><div class="plans">${[['gold','14.99','The foundation for sharper bets.',['Pre-match sportsbook EV bets','Searchable book & league filters','Bet tracking & CLV analysis']],['plus','19.99','A wider view of the market.',['Everything in Gold','Arbitrage analysis','Side-by-side prices & bet links']],['fantasy','29.99','Built for your fantasy lineup.',['Fantasy-app pre-match EV bets','Fantasy Parlay Builder','Bet tracking & CLV analysis']],['platinum','99.99','Every tool. Every opportunity.',['Everything in all memberships','Live EV bets','Pre-match / live switching','Sportsbooks + fantasy apps']]].map(([id,price,desc,items])=>`<article class="plan ${id==='platinum'?'highlight':''}">${id==='platinum'?'<span class="popular">THE COMPLETE EDGE</span>':''}<div class="eyebrow">${id==='gold'?'01':id==='plus'?'02':id==='fantasy'?'03':'04'} / MEMBERSHIP</div><h2>${names[id]}</h2><p>${desc}</p><div class="price">$${price}<small> / month</small></div><button class="${id==='platinum'?'primary':''}" onclick="choose('${id}')">${plan===id?'Current membership':window.sharpAuth?.profile?.requestedPlan===id?'Selected '+names[id]:'Choose '+names[id]} ↗</button><ul>${items.map(i=>`<li>${i}</li>`).join('')}</ul></article>`).join('')}</div><p class="mobile-note" style="text-align:center;margin-top:25px">New accounts start as Guest. Choosing a plan saves your preference; payment and activation are not available yet. <a href="#billing" style="color:var(--gold);text-decoration:underline">Subscription details</a></p><div class="upgrade-note"><div><span class="eyebrow">NEED THE ALL-APP BUILDER?</span><h3>Ask about Fantasy+.</h3><p>Fantasy+ expands the Parlay Builder from fantasy apps to sportsbook selections. Contact the SharpEdge sales team to discuss access and pricing.</p></div><button onclick="salesInfo()">Contact sales ↗</button></div><div class="faq"><h2>Good questions. Clear answers.</h2><details><summary>What’s the difference between Gold and Gold Plus?</summary><p>Gold includes pre-match sportsbook EV opportunities. Gold Plus includes the same tools and adds the arbitrage workspace.</p></details><details><summary>Does Fantasy Package include sportsbook EV?</summary><p>Fantasy Package focuses on pre-match EV for fantasy apps and the Parlay Builder. Platinum combines fantasy and sportsbook tools, plus live EV.</p></details><details><summary>Does positive EV guarantee a winning bet?</summary><p>No. Expected value is an estimate based on probability and price. Individual bets can lose, and market prices and model assumptions can change.</p></details><details><summary>How does this prototype work?</summary><p>Sign in with Google to create your account. Your bet journal and bankroll settings are saved privately across devices. Live market access requires an active membership. Billing and sportsbook deep links are not connected yet.</p></details></div>`}function salesInfo(){$('#modal').innerHTML=`<div class="eyebrow">FANTASY+ / SALES</div><h2>All-app builder access</h2><p>Contact the SharpEdge sales team to discuss Fantasy+ pricing and access. A sales channel is not connected in this design preview.</p><button class="primary" onclick="$('#modal').close()">Close</button>`;$('#modal').showModal()}function choose(p){requestMembership(p)}function account(){showAccount()}function locked(p){if(!currentAccount)return signInPage();const req={ev:'Gold, Gold Plus or Platinum',live:'Platinum',arbitrage:'Gold Plus or Platinum',parlay:'Fantasy Package, Fantasy+ or Platinum',analysis:'any paid membership'};return `<div class="locked"><div class="symbol">⌑</div><div class="eyebrow">YOUR NEXT ADVANTAGE</div><h2>Unlock ${p==='live'?'live EV':p==='ev'?'positive EV bets':p==='parlay'?'the Parlay Builder':p==='analysis'?'your bet analysis':'arbitrage analysis'}.</h2><p>This tool is included with ${req[p]}. Choose a membership to access the insights behind your next decision.</p><button class="primary" onclick="go('pricing')">Explore memberships ↗</button><p style="font-size:11px">Account details: <button onclick="account()" style="color:var(--gold);border:0;padding:0">My account</button></p></div>`}function filter(type){const current=type==='book'?book:league;return `<div class="filter"><button onclick="toggleFilter('${type}')">${current} <span style="float:right;margin-left:18px">⌄</span></button><div id="${type}-menu" class="filter-menu" hidden><input aria-label="Search ${type}" placeholder="Search ${type}…" oninput="searchOptions('${type}',this.value)"><div id="${type}-options">${filterOptions(type,'')}</div></div></div>`}function filterOptions(type,q){return (type==='book'?(route()==='parlay'&&builderMode==='fantasy'?['All books','PrizePicks','Underdog']:books).filter(v=>v==='All books'||(bookAllowed(v)&&(route()==='parlay'&&builderMode==='all'?['Sportsbook','Fantasy player picks','Prediction/exchange'].includes(bookCategory(v)):route()==='ev'&&(plan==='fantasy'||plan==='fantasyplus'||market==='fantasy')?bookCategory(v)==='Fantasy player picks':['Sportsbook','Prediction/exchange'].includes(bookCategory(v))))):leagues).filter(v=>v.toLowerCase().includes(q.toLowerCase())).map(v=>`<button onclick="setFilter('${type}','${v}')">${type==='book'&&v!=='All books'?badge(v):''}<span>${v}</span></button>`).join('')||'<p class="muted">No matches</p>'}function toggleFilter(t){const el=$('#'+t+'-menu');el.hidden=!el.hidden;if(!el.hidden)el.querySelector('input').focus()}function searchOptions(t,q){$('#'+t+'-options').innerHTML=filterOptions(t,q)}function setFilter(t,v){if(t==='book')book=v;else league=v;render()}async function refreshOdds(button){if(button.disabled)return;button.disabled=true;button.setAttribute('aria-busy','true');button.classList.add('refreshing');const started=performance.now(),refreshUID=currentAccount?.uid,refreshPlan=plan;let failed=false;try{if(window.__SHARPEDGE_SERVER__){const response=await window.sharpAuth.fetch('/api/feeds');if(!response.ok)throw new Error('Feed unavailable');const feed=await response.json();if(currentAccount?.uid!==refreshUID||plan!==refreshPlan||!(Date.parse(currentAccount.membershipExpiresAt)>Date.now()))return;window.__SHARPEDGE_FEED__=feed;data=feed.ev;arbs=feed.arbs}}catch{failed=true}await new Promise(resolve=>setTimeout(resolve,Math.max(0,650-(performance.now()-started))));book='All books';league='All leagues';empty=false;render();if(failed)notify('Could not refresh odds. Try again shortly.')}function toolbar(count,tabs=false){return `<div class="toolbar">${tabs?`<div class="tabs"><button class="${mode==='prematch'?'selected':''}" onclick="setMode('prematch')">Pre-match</button><button class="${mode==='live'?'selected':''}" onclick="setMode('live')"><span class="dot"></span> Live</button></div>`:''}${filter('book')}${filter('league')}<button class="refresh-btn" onclick="refreshOdds(this)" aria-label="Refresh odds and reset filters" title="Refresh odds and reset filters"><span aria-hidden="true">↻</span></button><span class="count">${count} opportunities · Highest Kelly first</span><button style="font-size:10px" onclick="empty=!empty;render()">${empty?'Show sample data':'Preview empty state'}</button></div>`}function setMode(m){mode=m;if(m==='live')market='sportsbook';render()}function emptyView(){return `<div class="empty"><div class="symbol">⌕</div><h2>No opportunities right now.</h2><p>Nothing matches this view at the moment. Check back later or adjust your filters to explore other markets.</p><button onclick="refreshOdds(this)">Reset filters & refresh ↻</button></div>`}function filtered(arr){return empty?[]:arr.filter(d=>offerAllowed(d)&&(book==='All books'||d.book===book||(book==='Hard Rock Bet'&&d.book==='Hard Rock'))&&(league==='All leagues'||d.league===league)).sort((a,b)=>(b.kellyFull??-1)-(a.kellyFull??-1)||b.ev-a.ev)}function kellyFraction(odds,fair){const offered=decimal(odds),p=1/decimal(fair);return Math.max(0,Math.min(1,(p*offered-1)/(offered-1)))}
