function evTable(rows,preview=false){return `<div class="table-wrap"><table class="ev-table"><thead><tr><th>EV %</th><th>Selection</th><th>Event</th><th>Sportsbook</th><th>Best odds</th><th>Suggested bet</th><th></th></tr></thead><tbody>${rows.map(d=>{const amount=suggestedAmount(d);return `<tr ${preview?'':`class="opportunity-row" onclick="rowOdds(event,'ev',${d.id},'${d.book}')" tabindex="0" onkeydown="rowOddsKey(event,'ev',${d.id},'${d.book}')"`}><td class="ev">+${d.ev.toFixed(2)}%</td><td class="selection-cell"><strong>${d.bet}</strong><small>${d.name}</small>${preview?'':`<button class="compare-toggle" aria-expanded="false" aria-controls="odds-ev-${d.id}" onclick="toggleOdds(this.closest('tr'),'ev',${d.id},'${d.book}')">Compare books <span>⌄</span></button>`}</td><td><strong>${d.game}</strong><small>${d.league} &nbsp; · &nbsp; ${localEventTime(d.time)}</small></td><td>${badge(d.book)}</td><td class="odds-cell"><strong class="best-odds ${d.odds==='Entry-based'?'entry-odds':''}">${d.odds}</strong><small>Fair: ${d.fair}</small></td><td class="suggestion-cell">${amount===null?'<strong>—</strong><small>Set entry payout in Builder</small>':`<strong class="stake-amount">${money(amount)}</strong><small>${(fullKelly(d)*25).toFixed(2)}% Kelly</small>`}</td><td><button class="bet-btn" onclick="${preview?'explore()':`openBet(${d.id},'${d.book}')`}">View bet ↗</button></td></tr>`}).join('')}</tbody></table></div>`}
