function localEventTime(value){if(!value)return 'Time TBD';const date=new Date(value);if(Number.isNaN(date.getTime()))return value;const parts=new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',hour12:true,timeZoneName:'short'}).formatToParts(date);const part=type=>parts.find(p=>p.type===type)?.value||'';return `${part('hour')}:${part('minute')} ${part('dayPeriod')} ${part('timeZoneName')}`.trim()}
function openBet(id,b,price=null){if(b==='PrizePicks'||b==='Underdog'){go('parlay');return;}let d={...data.find(x=>x.id===id)};if(price!==null)d.odds=price;const dialog=$('#modal');dialog.innerHTML=`<div class="eyebrow">SAMPLE BET / ${b}</div><h2>${d.name}</h2><p>${d.bet}<br>${d.game}<br>Displayed sample price: <strong style="color:var(--gold)">${b==='PrizePicks'||b==='Underdog'?'1.90×':d.odds}</strong></p><p>In production, this action opens the exact market at ${b}. A verified sportsbook deep link is not connected in this prototype.</p><label>Stake ($)<input id="stake" type="number" min="0.01" step="0.01" value="10"></label><div class="actions"><button onclick="$('#modal').close()">Close</button><button class="primary" onclick="track(${id},'${b}','${d.odds}')">Log sample bet →</button></div><p style="font-size:10px">Logging a sample bet does not place a wager.</p>`;dialog.showModal()}async function track(id,b,price=null){if(!currentAccount)return account();if(tracked.length>=500)return notify('Your journal holds up to 500 bets. Remove an old entry before adding another.');let stake=Number($('#stake').value);if(!Number.isFinite(stake)||stake<=0)return notify('Enter a valid positive stake.');let d=data.find(x=>x.id===id);tracked.push({...d,odds:price??d.odds,book:b,stake,uid:Date.now(),close:null});try{await persist();$('#modal').close();notify('Bet saved to your account')}catch{tracked.pop();notify('Bet could not be saved. Please try again.')}}const sampleArbs=[{id:1,name:'Jayson Tatum',prop:'27.5 points',game:'BOS @ NYK · NBA',league:'NBA',left:'DraftKings',right:'FanDuel',a:110,b:105,ev:3.73},{id:3,name:'Aaron Judge',prop:'1.5 total bases',game:'NYY @ BOS · MLB',league:'MLB',left:'BetMGM',right:'Hard Rock',a:125,b:-115,ev:1.79},{id:2,name:'Lamar Jackson',prop:'48.5 rushing yards',game:'BAL @ PIT · NFL',league:'NFL',left:'FanDuel',right:'DraftKings',a:115,b:-105,ev:2.43}];let arbs=window.__SHARPEDGE_SERVER__?(window.__SHARPEDGE_FEED__?.arbs??[]):sampleArbs;for(const a of arbs)if(!Number.isFinite(a.ev))a.ev=(1/(1/decimal(a.a)+1/decimal(a.b))-1)*100;function arbSideLabel(d,side){const raw=side==='a'?d.side1:d.side2;if(d.market==='moneyline')return raw||d.name;if(d.market==='spreads'){const line=Number(side==='a'?d.line1:d.line2);return `${raw||d.name}${Number.isFinite(line)?' '+(line>0?'+':'')+line:''}`}return raw|| (side==='a'?'Over':'Under')}function arbSelection(d,side){const label=arbSideLabel(d,side);return d.market==='moneyline'||d.market==='spreads'?label:`${label} ${d.prop}`}function arbPage(){let rows=empty?[]:arbs.filter(d=>bookAllowed(d.left)&&bookAllowed(d.right)&&(book==='All books'||d.left===book||d.right===book||(book==='Hard Rock Bet'&&(d.left==='Hard Rock'||d.right==='Hard Rock')))&&(league==='All leagues'||d.league===league)).sort((a,b)=>(b.kellyFull??-1)-(a.kellyFull??-1)||b.ev-a.ev);return head('TWO SIDES. ONE OPPORTUNITY.','Arbitrage','Compare opposing prices across books in a single, focused view.')+toolbar(rows.length)+(!can('arbitrage')?locked('arbitrage'):!rows.length?(empty?emptyView():regionEmpty()):`<div class="preview table-wrap"><table class="arb-table"><thead><tr><th>Place side A</th><th>Side A / Best odds</th><th class="arb-center">Match / Market</th><th>Side B / Best odds</th><th>Return</th><th>Place side B</th></tr></thead><tbody>${rows.map(d=>`<tr class="opportunity-row" onclick="rowOdds(event,'arb',${d.id})" tabindex="0" onkeydown="rowOddsKey(event,'arb',${d.id})"><td><button class="bet-btn" onclick="arbBet(${d.id},'a')">View bet ↗</button></td><td><div class="arb-price-pair">${badge(d.left)}<div><span class="arb-side">${arbSideLabel(d,'a')}</span><strong class="arb-odds">${formatOdds(d.a)}</strong></div></div></td><td class="arb-center"><strong>${d.market==='moneyline'||d.market==='spreads'?d.game:d.name}</strong><small>${d.prop}</small>${d.market==='moneyline'||d.market==='spreads'?'':`<small>${d.game}</small>`}<small>${d.league} · ${localEventTime(d.time)}</small><button class="compare-toggle" aria-expanded="false" aria-controls="odds-arb-${d.id}" onclick="toggleOdds(this.closest('tr'),'arb',${d.id})">Compare books <span>⌄</span></button></td><td><div class="arb-price-pair">${badge(d.right)}<div><span class="arb-side">${arbSideLabel(d,'b')}</span><strong class="arb-odds">${formatOdds(d.b)}</strong></div></div></td><td class="ev">+${d.ev.toFixed(2)}%</td><td><button class="bet-btn" onclick="arbBet(${d.id},'b')">View bet ↗</button></td></tr>`).join('')}</tbody></table></div><p class="mobile-note">Theoretical returns assume both legs fill at shown prices with matching settlement rules. Prices, limits, and availability can change.</p>`)}function arbBet(id,side,selectedBook=null,selectedPrice=null){let d=arbs.find(a=>a.id===id);$('#modal').innerHTML=`<div class="eyebrow">ARBITRAGE / ${side==='a'?'SIDE A':'SIDE B'}</div><h2>${d.name}</h2><p>${arbSelection(d,side)} at ${selectedBook??(side==='a'?d.left:d.right)}<br>Odds: ${selectedPrice??formatOdds(side==='a'?d.a:d.b)}</p><p>This prototype previews the one-tap sportsbook handoff. Exact market links will be supplied by the production odds API.</p><button class="primary" onclick="$('#modal').close()">Done</button>`;$('#modal').showModal()}function builderSource(){if(window.__SHARPEDGE_SERVER__)return data.filter(d=>!d.live).map(d=>({...d,kind:bookCategory(d.book)==='Fantasy player picks'?'fantasy':'sportsbook'})).filter(d=>builderMode==='all'||d.kind==='fantasy');return builderMode==='fantasy'?fantasyPicks.map(d=>({...d,kind:'fantasy'})):[...fantasyPicks.map(d=>({...d,kind:'fantasy'})),...data.filter(d=>!d.live).map(d=>({...d,kind:'sportsbook'}))]}
function builderKey(d){return (d.kind==='fantasy'?'f:':'s:')+encodeURIComponent(JSON.stringify([d.sourceId??null,d.book,d.bet,d.game])).replace(/'/g,'%27')}
function legFor(key){return builderSource().find(d=>builderKey(d)===key)}
function reconcileBuilder(){const previous=legs.length;legs=legs.filter(key=>{const d=legFor(key);return d&&offerAllowed(d)});if(previous!==legs.length){payoutOverride=null;notify('Unavailable selections were removed. Review current prices before saving.')}}
